/* From Uiverse.io by Df12345677 - Tags: button, animated, add */
.__UIV_SCOPE__ .button {
  height: 60px;
  width: 200px;
  background-color: #132233;
  border: 2px solid rgb(182, 128, 128);
  color: #eee;
  transition: .6s;
  font-size: 15px;
  border-radius: 50px;
  display: flex;
  justify-content: center;
  align-items: center;
  /* padding: 20px; */
  overflow: hidden;
}

.__UIV_SCOPE__ .button span {
  transform: translateX(10px);
  transition: .5s;
}

.__UIV_SCOPE__ .button svg {
  transform: translateX(-300px);
  transition: .6s;
  z-index: 3;
  height: 20px;
}

.__UIV_SCOPE__ .button:hover {
  width: 60px;
  background-color: rgba(51, 34, 51, 0.815);
  box-shadow: 20px 20px 96px #bebebe,-20px -20px 96px #ffffff;
}

.__UIV_SCOPE__ .button:hover svg {
  transform: translateX(-5px);
}

.__UIV_SCOPE__ .button:hover span {
  transform: translateY(70px);
  font-size: .1rem;
}
